/** 十二運星. 인덱스 0=长生 … 11=养. */
export const CHANG_SHENG = Object.freeze([
  "长生", "沐浴", "冠带", "临官", "帝旺", "衰",
  "病", "死", "墓", "绝", "胎", "养",
]);

/**
 * 일간별 十二運星 위상 오프셋. 소비자는 `(오프셋 ± 지지index) mod 12` 로 CHANG_SHENG 을
 * 고른다 — 양간(甲丙戊庚壬)은 +, 음간(乙丁己辛癸)은 −.
 */
export const CHANG_SHENG_OFFSET = Object.freeze({
  甲: 1, 丙: 10, 戊: 10, 庚: 7, 壬: 4,
  乙: 6, 丁: 9, 己: 9, 辛: 0, 癸: 3,
});

/** 旬(순) 6벌과 그 旬空(공망). 인덱스가 서로 대응한다. */
const XUN = Object.freeze(["甲子", "甲戌", "甲申", "甲午", "甲辰", "甲寅"]);
const XUN_KONG = Object.freeze(["戌亥", "申酉", "午未", "辰巳", "寅卯", "子丑"]);

const GAN = "甲乙丙丁戊己庚辛壬癸";
const ZHI = "子丑寅卯辰巳午未申酉戌亥";

/**
 * 간지 2글자가 속한 旬 인덱스. 천간과 지지의 인덱스 차를 12로 감아 2로 나눈다.
 *
 * 🔴 원본은 1-based `GAN`/`ZHI` 배열에서 문자열을 찾아 인덱스를 뺐는데, 두 인덱스가 함께 1씩
 * 밀려 있어 차가 같다 — 0-based 산술과 동치다(가드 ③ 이 60갑자 전건으로 매번 확인한다).
 * 🔴 원본은 간지가 아닌 문자열에 **예외를 던졌다.** 여기서는 -1 을 돌려 호출부가 `""` 를 내게
 * 한다. 소비자에 그 경로는 없다(기둥은 비었으면 앞에서 걸리고, 아니면 항상 2글자 한자다).
 */
function xunIndex(ganZhi) {
  const text = String(ganZhi || "");
  // 🔴 빈 문자열을 먼저 걷어낸다 — "".charAt(0) 은 "" 이고 indexOf("") 는 0 이라
  // 길이를 안 보면 빈 입력이 甲子 로 샌다(가드 ③ 이 잡았다).
  if (text.length < 2) return -1;
  const stem = GAN.indexOf(text.charAt(0));
  const branch = ZHI.indexOf(text.charAt(1));
  if (stem < 0 || branch < 0) return -1;
  return Math.floor(((stem - branch + 12) % 12) / 2);
}

/** 간지가 속한 旬(예: `甲子`). 간지가 아니면 `""`. */
export function getXun(ganZhi) {
  const index = xunIndex(ganZhi);
  return index < 0 ? "" : XUN[index];
}

/** 간지의 旬空(공망, 예: `戌亥`). 간지가 아니면 `""`. */
export function getXunKong(ganZhi) {
  const index = xunIndex(ganZhi);
  return index < 0 ? "" : XUN_KONG[index];
}
